using System.Diagnostics;using System.Text.Json;using Dip.Application.Features.Intelligence;using Dip.Application.Features.QualityAutomation;
namespace Dip.Infrastructure.Intelligence;
public sealed class RegressionRunner:IRegressionRunner
{
 readonly IQaWorkspaceResolver _workspace;public RegressionRunner(IQaWorkspaceResolver workspace){_workspace=workspace;}
 public async Task<RegressionResult> FindOriginAsync(RegressionRequest r,string artifactRoot,CancellationToken ct){var ws=_workspace.Resolve(r.WorkspaceRelativePath);var tested=new List<string>();async Task<(int,string,string)> Git(params string[] args){var psi=new ProcessStartInfo("git"){WorkingDirectory=ws,UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var a in args)psi.ArgumentList.Add(a);using var p=Process.Start(psi)??throw new InvalidOperationException("git not found");var o=await p.StandardOutput.ReadToEndAsync(ct);var e=await p.StandardError.ReadToEndAsync(ct);await p.WaitForExitAsync(ct);return(p.ExitCode,o.Trim(),e.Trim());}var orig=(await Git("rev-parse","HEAD")).Item2;try{var list=await Git("rev-list","--ancestry-path","--reverse",$"{r.GoodCommit}..{r.BadCommit}");if(list.Item1!=0)throw new InvalidOperationException(list.Item3);var commits=list.Item2.Split('\n',StringSplitOptions.RemoveEmptyEntries);if(commits.Length==0)return new(null,tested,"NoRange",JsonSerializer.Serialize(new{error="No commits in range"}));int lo=0,hi=commits.Length-1;string? bad=null;while(lo<=hi){var mid=(lo+hi)/2;var c=commits[mid];await Git("checkout","--detach",c);tested.Add(c);var psi=new ProcessStartInfo(r.VerificationCommand){WorkingDirectory=ws,UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var a in r.VerificationArguments)psi.ArgumentList.Add(a);using var p=Process.Start(psi)??throw new InvalidOperationException("Verification command unavailable");using var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct);timeout.CancelAfter(TimeSpan.FromSeconds(Math.Clamp(r.TimeoutSeconds,5,1800)));bool pass;try{await p.WaitForExitAsync(timeout.Token);pass=p.ExitCode==0;}catch(OperationCanceledException)when(!ct.IsCancellationRequested){try{p.Kill(true);}catch{}pass=false;}if(pass)lo=mid+1;else{bad=c;hi=mid-1;}}var payload=JsonSerializer.Serialize(new{firstBadCommit=bad,tested});await File.WriteAllTextAsync(Path.Combine(artifactRoot,"regression-origin.json"),payload,ct);return new(bad,tested,bad is null?"Unresolved":"Resolved",payload);}finally{if(!string.IsNullOrWhiteSpace(orig))await Git("checkout","--detach",orig);}}
